INSERT INTO public.shops (id, owner_id, name, slug, category, location, address_display, whatsapp_number, logo_url, banner_url, is_live, verification_status, latitude, longitude, service_radius_km, delivery_zones, min_order_amount, free_delivery_threshold, delivery_fee_flat, delivery_fee_per_km, store_bio, announcement, business_hours, operating_status, accent_color) VALUES
  ('a0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000001', 'Tandoori Express', 'demo-tandoori', 'Fast Food & Restaurants', 'Satellite Town, Gujranwala', 'Grand Trunk Road, Satellite Town, Gujranwala', '0301-5551001', 'https://upload.wikimedia.org/wikipedia/commons/8/81/DZ6_2571_A_bright_red_scooter_parked_on_a_city_sidewalk_outside_shops_at_dusk_ready_for_a_quick_ride_through_the_bustling_streets.jpg', 'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=1200&q=80', true, 'approved', 32.1566, 74.187, 10, ARRAY['__pk_city__:Gujranwala', 'Satellite Town', 'Civil Lines', 'Model Town', 'Peoples Colony']::text[], 300, 1500, 99, 25, 'Fresh tandoor, wood-fired pizzas, juicy burgers & BBQ. Fast delivery across Satellite Town.', 'Free delivery on orders above Rs 1,500 — this week only!', 'Mon-Sun: 11 AM - 12 AM', 'Open Today: 11 AM - 12 AM', '#f97316'),
  ('a0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000002', 'Pizza Palace', 'demo-pizza', 'Fast Food & Restaurants', 'Civil Lines, Gujranwala', 'Court Road, Civil Lines, Gujranwala', '0301-5551002', 'https://upload.wikimedia.org/wikipedia/commons/8/81/DZ6_2571_A_bright_red_scooter_parked_on_a_city_sidewalk_outside_shops_at_dusk_ready_for_a_quick_ride_through_the_bustling_streets.jpg', 'https://live.staticflickr.com/203/512447057_28d85c21b2_b.jpg', true, 'approved', 32.1647, 74.1903, 8, ARRAY['__pk_city__:Gujranwala', 'Civil Lines', 'Cantt', 'Satellite Town', 'Model Town']::text[], 250, 2000, 149, 30, '20+ pizza flavours, fresh pasta & garlic bread. The family pizza spot of Civil Lines.', 'Family Pizza + 1.5L drink combo at Rs 1,499', 'Mon-Sun: 12 PM - 1 AM', 'Open Today: 12 PM - 1 AM', '#dc2626'),
  ('a0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000003', 'Al-Madina Super Store', 'demo-grocery', 'Grocery & Kiryana', 'Model Town, Gujranwala', 'Model Town Main Bazaar, Gujranwala', '0301-5551003', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80', true, 'approved', 32.1505, 74.1781, 12, ARRAY['__pk_city__:Gujranwala', 'Model Town', 'Peoples Colony', 'Satellite Town', 'Azizabad']::text[], 200, 2500, 79, 20, 'Your neighbourhood kiryana + supermarket. Daily staples, snacks, dairy & household.', 'Pack of 6 mineral water — only Rs 550!', 'Mon-Sun: 8 AM - 11 PM', 'Open Today: 8 AM - 11 PM', '#16a34a'),
  ('a0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000004', 'Sweet Bites Bakery', 'demo-bakery', 'Bakery & Sweets', 'Peoples Colony, Gujranwala', 'Peoples Colony Main Road, Gujranwala', '0301-5551004', 'https://live.staticflickr.com/5084/5276348140_da708cf2a1_b.jpg', 'https://live.staticflickr.com/4144/5085764791_5db59cc8ac_b.jpg', true, 'approved', 32.1521, 74.195, 8, ARRAY['__pk_city__:Gujranwala', 'Peoples Colony', 'Civil Lines', 'Model Town', 'Kohinoor Town']::text[], 250, 1500, 99, 25, 'Fresh bread daily, custom cakes, pastries, rusk & desi sweets. Order for home or office.', 'Order cakes 24 hrs ahead — free custom message on top', 'Mon-Sun: 7 AM - 11 PM', 'Open Today: 7 AM - 11 PM', '#d97706'),
  ('a0000000-0000-4000-8000-000000000005', 'd0000000-0000-4000-8000-000000000005', 'Dera Desi Khana', 'demo-desi', 'Fast Food & Restaurants', 'Cantt, Gujranwala', 'Gujranwala Cantt Main Road, Gujranwala', '0301-5551005', 'https://upload.wikimedia.org/wikipedia/commons/8/81/DZ6_2571_A_bright_red_scooter_parked_on_a_city_sidewalk_outside_shops_at_dusk_ready_for_a_quick_ride_through_the_bustling_streets.jpg', 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=1200&q=80', true, 'approved', 32.17, 74.21, 10, ARRAY['__pk_city__:Gujranwala', 'Cantt', 'Civil Lines', 'Gulshan-e-Iqbal', 'Rasoolpura']::text[], 300, 1800, 89, 20, 'Sindhi & Punjabi desi khana — karahi, nihari, biryani, haleem & tandoori naan.', 'Chicken Karahi + 4 naan combo at Rs 1,999', 'Mon-Sun: 11 AM - 12 AM', 'Open Today: 11 AM - 12 AM', '#ca8a04'),
  ('a0000000-0000-4000-8000-000000000006', 'e0000000-0000-4000-8000-000000000006', 'ToyKart', 'demo-toys', 'Toys & Baby Care', 'Kohinoor Town, Gujranwala', 'Kohinoor Town Main Boulevard, Gujranwala', '0301-5551006', 'https://images.unsplash.com/photo-1558060370-d644479cb6f7?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1558060370-d644479cb6f7?auto=format&fit=crop&w=1200&q=80', true, 'approved', 32.148, 74.17, 8, ARRAY['__pk_city__:Gujranwala', 'Kohinoor Town', 'Peoples Colony', 'Satellite Town', 'Azizabad']::text[], 150, 2000, 119, 30, 'Action figures, remote cars, building blocks, dolls & educational toys for all ages.', 'Gift combos — flat 10% off on two or more toys', 'Mon-Sun: 10 AM - 10 PM', 'Open Today: 10 AM - 10 PM', '#8b5cf6'),
  ('a0000000-0000-4000-8000-000000000007', 'e0000000-0000-4000-8000-000000000007', 'Trendy Threads', 'demo-clothes', 'Fashion & Apparel', 'Rasoolpura, Gujranwala', 'Rasoolpura Main Bazaar, Gujranwala', '0301-5551007', 'https://live.staticflickr.com/2811/12117243725_2e9aa20710_b.jpg', 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1200&q=80', true, 'approved', 32.1595, 74.201, 10, ARRAY['__pk_city__:Gujranwala', 'Rasoolpura', 'Civil Lines', 'Cantt', 'Nowshera Virkan']::text[], 300, 2500, 129, 25, 'Men''s & kids'' fashion — polos, shirts, jeans, kurtas & shalwar kameez in fresh designs.', 'Buy 2 kurta designs, get 5% off — mix & match', 'Mon-Sun: 10 AM - 11 PM', 'Open Today: 10 AM - 11 PM', '#0ea5e9')
